}
raw_code = ((contract.grade_id and contract.grade_id.grade_code) or (employee.grade_id and employee.grade_id.grade_code) or '').strip().upper()
clean_code = raw_code.replace('GRADE', '').strip()
emp_grade = contract.grade_id or employee.grade_id
grade_tab_val = 0.0
if emp_grade and rule and hasattr(rule, 'grade_rules') and rule.grade_rules:
    matching = rule.grade_rules.filtered(lambda r: r.grade2 == emp_grade or (r.grade2 and emp_grade and (r.grade2.grade_code or '').strip().upper() == (emp_grade.grade_code or '').strip().upper()))
    if matching:
        grade_tab_val = matching[0].value or matching[0].base_salary or 0.0
grade_val = grade_tab_val or rep_map.get(clean_code, 0.0)
