pos_tab_val = 0.0
if emp_pos and rule and hasattr(rule, 'position_rules') and rule.position_rules:
    matching = rule.position_rules.filtered(lambda r: r.position == emp_pos)
    if matching:
        pos_tab_val = matching[0].value or 0.0
result = pos_tab_val if pos_tab_val > 0 else grade_val

ou = contract.operating_unit_id or employee.default_operating_unit_id
if not ou and employee.department_id:
    ou = employee.department_id.operating_unit_id

ou_rate = 0.0
if ou:
    try:
        ou_rate = (ou.hardship_allowance or 0.0) / 100.0
    except Exception:
        ou_rate = 0.0
    if ou_rate == 0.0:
        try:
            contract.env.cr.execute("SELECT hardship_allowance FROM operating_unit WHERE id = %s", (ou.id,))
            row = contract.env.cr.fetchone()
            if row and row[0]:
                ou_rate = float(row[0]) / 100.0
        except Exception:
            pass

if ou_rate > 0:
    result = categories.BASIC * ou_rate
else:
    result = 0.0

