ou = contract.operating_unit_id or employee.default_operating_unit_id
if not ou and employee.department_id:
    ou = employee.department_id.operating_unit_id

ou_exempt_rate = 0.0
if ou:
    try:
        ou_exempt_rate = (ou.tax_exempt or 0.0) / 100.0
    except Exception:
        ou_exempt_rate = 0.0
    if ou_exempt_rate == 0.0:
        try:
            contract.env.cr.execute("SELECT tax_exempt FROM operating_unit WHERE id = %s", (ou.id,))
            row = contract.env.cr.fetchone()
            if row and row[0]:
                ou_exempt_rate = float(row[0]) / 100.0
        except Exception:
            pass

hardship_exempt = categories.BASIC * ou_exempt_rate

# Fuel Exemption (statutory 600 max)
fuel_exempt = 0.0
if (contract.special_car_allowance or 0) == 0 and (contract.fuel_exempted_1 or 0) != 1:
    f_val = 0.0
    try:
        f_val = float(FUEL)
    except Exception:
        f_val = float(contract.fuel_allowance or 0.0)
    fuel_exempt = min(f_val, 600.0)

# Transportation Exemption (statutory 2200 max)
trans_exempt = 0.0
if (contract.special_car_allowance or 0) == 0:
    t_val = 0.0
    try:
        t_val = float(TRANSPORT)
    except Exception:
        t_val = float(contract.transportation_allowance or 0.0)
    trans_exempt = min(t_val, 2200.0)

